import React from 'react';
import FilmCard from './FilmCard';

// Приймаємо films як пропс (зовнішні дані)
const FilmsGallery = ({ films }) => {
    return (
        <section className="gallery">
            <div className="grid">
                {films.map((f) => (
                    <FilmCard key={f.id} film={f} />
                ))}
            </div>
        </section>
    );
};

export default FilmsGallery;
